        chunk = probes[i:i+CH]
        d = os.path.join(ROOT, "chunk"); shutil.rmtree(d, ignore_errors=True)
        os.makedirs(d)
        for p in chunk:
            open(os.path.join(d, p["id"] + ".dart"), "w").write(p["src"])
        # FIX 2026-08-18 (log 030 decision 12): the previous form
        # scraped PLAIN `dart analyze` output and called ANY diagnostic
        # a REFUSE -- warnings and lints included -- and recorded an
        # empty detail.  dart reports `dead_code` on the right operand
        # of `true || b` and `false && b`, so a short-circuit lint was
        # being read as a type refusal.  --format=machine gives
        # SEVERITY|TYPE|CODE|FILE|LINE|COL|LEN|MESSAGE; only ERROR is a
        # refusal, which is what the other eight harnesses measure
        # (g++/javac/rustc do not fail on warnings either).
        r = subprocess.run([DART, "analyze", "--format=machine", "."],
                           capture_output=True, text=True, cwd=d)
        bad, why = {}, {}
        for line in ((r.stdout or "") + (r.stderr or "")).splitlines():
            f = line.split("|")
            if len(f) < 8:
                continue
            sev, code, path, msg = f[0], f[2], f[3], f[7]
            base = os.path.basename(path)
            if not base.endswith(".dart"):
                continue
            pid = base[:-5]
            if sev == "ERROR":
                bad[pid] = code
                why[pid] = (code + " " + msg)[:200]
            else:
