        for p in chunk:
            v = "REFUSE" if p["id"] in bad else "ACCEPT"
            verdicts[p["id"]] = v
            emit(p["id"], v, why.get(p["id"], "") if v == "REFUSE" else "")
        pg.tick(len(chunk))
